import pandas as pd
import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
from pathlib import Path

class BrakingAnalyzer:
    def __init__(self, telemetry_file="results/simulation_telemetry.csv"):
        self.file_path = Path(telemetry_file)
        if not self.file_path.exists():
            raise FileNotFoundError(f"Missing {self.file_path}. Run braking.py first!")
        
        # Load the artifact generated by the simulation
        self.df = pd.read_csv(self.file_path)
        
        # Include the zero-input sample immediately before the brake ramp.
        braking_rows = self.df.index[self.df["brake_input"] > 1.0e-6]
        if len(braking_rows) > 0:
            start_index = max(int(braking_rows[0]) - 1, 0)
            self.braking_df = self.df.iloc[start_index:].copy()
        else:
            self.braking_df = self.df.iloc[0:0].copy()
        
        # Zero out the time and distance relative to brake onset
        if not self.braking_df.empty:
            start_time = self.braking_df["time"].iloc[0]
            start_x = self.braking_df["Chassis_x"].iloc[0]
            self.braking_df["braking_time"] = self.braking_df["time"] - start_time
            self.braking_df["braking_dist"] = self.braking_df["Chassis_x"] - start_x
            
            # Identify the final stopping point metrics
            self.stop_time = self.braking_df["braking_time"].iloc[-1]
            self.stop_dist = self.braking_df["braking_dist"].iloc[-1]

    def generate_graphs(self, output_filename="results/braking_performance.png"):
        print("Generating performance graphs...")
        fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(8, 8), constrained_layout=True)
        
        speed_kph = self.braking_df["speed_mps"] * 3.6
        stop_speed_kph = float(speed_kph.iloc[-1])
        
        # --- Graph 1: Speed vs Time ---
        ax1.plot(self.braking_df["braking_time"], speed_kph, color="tab:blue", linewidth=2)
        ax1.set(xlabel="Time after brake application (s)", ylabel="Speed (km/h)", title="100-0 km/h Braking Profile")
        ax1.grid(True, alpha=0.3)
        ax1.set_ylim(bottom=0)
        
        # Add stopping time annotation
        ax1.scatter([self.stop_time], [stop_speed_kph], color="red", zorder=3)
        ax1.axvline(self.stop_time, color="red", linestyle="--", alpha=0.7)
        ax1.annotate(
            f'Stopping time = {self.stop_time:.2f} s',
            xy=(self.stop_time, stop_speed_kph), xytext=(-150, 35),
            textcoords="offset points", arrowprops={"arrowstyle": "->"},
            color="darkred", fontweight="bold"
        )
        
        # --- Graph 2: Speed vs Distance ---
        ax2.plot(self.braking_df["braking_dist"], speed_kph, color="tab:green", linewidth=2)
        ax2.set(xlabel="Distance after brake application (m)", ylabel="Speed (km/h)")
        ax2.grid(True, alpha=0.3)
        ax2.set_ylim(bottom=0)
        
        # Add stopping distance annotation
        ax2.scatter([self.stop_dist], [stop_speed_kph], color="red", zorder=3)
        ax2.axvline(self.stop_dist, color="red", linestyle="--", alpha=0.7)
        ax2.annotate(
            f'Stopping distance = {self.stop_dist:.2f} m',
            xy=(self.stop_dist, stop_speed_kph), xytext=(-190, 35),
            textcoords="offset points", arrowprops={"arrowstyle": "->"},
            color="darkred", fontweight="bold"
        )
        
        # Ensure the output directory exists before saving
        out_file = Path(output_filename)
        out_file.parent.mkdir(parents=True, exist_ok=True)
        
        fig.savefig(out_file, dpi=180)
        plt.close(fig)
        print(f"Graph saved to {out_file.resolve()}")

if __name__ == "__main__":
    analyzer = BrakingAnalyzer()
    analyzer.generate_graphs()
